import { io } from "socket.io-client";
import { SOCKET_PATH, SOCKET_URL } from "./config";
import { showSnackbar } from "./redux/slices/app";
import axios from "./utils/axios";

export class WebSocketService {
  constructor() {
    this.socket = null;
    this.connected = false;
    this.subscriptions = [];
    this.messageQueue = [];
    this.refreshAttempted = false;
  }

  connect({ dispatch }) {
    if (this.socket) return this.socket;

    this.socket = io(SOCKET_URL, {
      path: SOCKET_PATH,
      withCredentials: true,
      transports: ["websocket", "polling"],
      reconnection: true,
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
    });

    this.socket.on("connect", () => {
      this.connected = true;
      this.refreshAttempted = false;
      while (this.messageQueue.length > 0) {
        const { event, body } = this.messageQueue.shift();
        this.socket.emit(event, body);
      }
    });

    this.socket.on("disconnect", () => {
      this.connected = false;
    });

    this.socket.on("connect_error", async (error) => {
      this.connected = false;
      if (!this.refreshAttempted) {
        this.refreshAttempted = true;
        try {
          await axios.post("/auth/refresh");
          this.socket?.connect();
          return;
        } catch (_) {
          // Report the original realtime error below.
        }
      }
      if (dispatch) {
        dispatch(showSnackbar({
          severity: "error",
          message: error?.message === "xhr poll error" ? "Realtime connection failed" : error?.message,
        }));
      }
    });

    this.subscriptions.forEach(({ event, handler }) => this.socket.on(event, handler));
    return this.socket;
  }

  disconnect() {
    if (this.socket) {
      this.socket.removeAllListeners();
      this.socket.disconnect();
      this.socket = null;
    }
    this.connected = false;
    this.subscriptions = [];
    this.messageQueue = [];
  }

  sendMessage(destination, body) {
    const event = this.eventName(destination);
    let payload = body;
    if (typeof body === "string") {
      try {
        payload = JSON.parse(body);
      } catch (_) {
        payload = body;
      }
    }

    if (this.socket?.connected) {
      this.socket.emit(event, payload);
    } else {
      this.messageQueue.push({ event, body: payload });
    }
  }

  subscribe(topic, callback) {
    const event = this.eventName(topic);
    const handler = (data) => callback(typeof data === "string" ? data : JSON.stringify(data));
    const subscription = {
      event,
      handler,
      unsubscribe: () => this.unsubscribe(subscription),
    };

    this.subscriptions.push(subscription);
    this.socket?.on(event, handler);
    return subscription;
  }

  unsubscribe(subscription) {
    if (!subscription) return;
    this.socket?.off(subscription.event, subscription.handler);
    this.subscriptions = this.subscriptions.filter((item) => item !== subscription);
  }

  unsubscribeAll() {
    [...this.subscriptions].forEach((subscription) => this.unsubscribe(subscription));
  }

  eventName(value) {
    return value.split("/").filter(Boolean).pop();
  }
}

const webSocketService = new WebSocketService();
export default webSocketService;
