import { Stack } from "@mui/material";
import React, { useEffect, useRef } from "react";
import { Navigate, Outlet } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import webSocketService from "../../webSocketService";
import useResponsive from "../../hooks/useResponsive";
import SideNav from "./SideNav";
import { FetchUserProfile, SelectConversation, showSnackbar } from "../../redux/slices/app";
import {
  UpdateDirectConversation,
  AddDirectConversation,
  AddDirectMessage,
  SetCurrentConversation,
  SetCurrentGroup,
  AddGroupConversation,
  UpdateGroupConversation,
  AddGroupMessage,
  ApplyGroupMessageDeletion,
  RemoveGroupConversation,
} from "../../redux/slices/conversation";
import AudioCallNotification from "../../sections/main/Audio/CallNotification";
import VideoCallNotification from "../../sections/main/Video/CallNotification";
import { PushToAudioCallQueue, UpdateAudioCallDialog, UpdateCallStatus, } from "../../redux/slices/audioCall";
import AudioCallDialog from "../../sections/main/Audio/CallDialog";
import VideoCallDialog from "../../sections/main/Video/CallDialog";
import { PushToVideoCallQueue, UpdateVideoCallDialog } from "../../redux/slices/videoCall";


const DashboardLayout = () => {


  const isDesktop = useResponsive("up", "md");
  const { user_id } = useSelector((state) => state.auth);
  const { open_audio_notification_dialog, open_audio_dialog } = useSelector((state) => state.audioCall);
  const { open_video_notification_dialog, open_video_dialog } = useSelector((state) => state.videoCall);
  const { isLoggedIn } = useSelector((state) => state.auth);
  const groupConversations = useSelector((state) => state.conversation.group_chat.conversations);
  const dispatch = useDispatch();
  const groupConversationsRef = useRef([]);

  useEffect(() => {
    groupConversationsRef.current = groupConversations || [];
  }, [groupConversations]);


  useEffect(() => {
    dispatch(FetchUserProfile());
  }, [dispatch]);

  const handleCloseAudioDialog = () => {
    dispatch(UpdateAudioCallDialog({ state: false }));
  };
  const handleCloseVideoDialog = () => {
    dispatch(UpdateVideoCallDialog({ state: false }));
  };

  const userId = user_id;

  useEffect(() => {
    const subscriptions = [];
    if (isLoggedIn && userId) {
      webSocketService.connect({ dispatch });

        const audio_call_notification = webSocketService.subscribe(`/user/${userId}/topic/audio_call_notification`, (data) => {
          const parsedResponse = JSON.parse(data);
          dispatch(PushToAudioCallQueue(parsedResponse.data));
          dispatch(UpdateCallStatus({ status: "RINGING" }));
        });
        subscriptions.push(audio_call_notification);

        const video_call_notification = webSocketService.subscribe(`/user/${userId}/topic/video_call_notification`, (data) => {
          const parsedResponse = JSON.parse(data);
          dispatch(PushToVideoCallQueue(parsedResponse.data));
        });
        subscriptions.push(video_call_notification);

        const new_message = webSocketService.subscribe(`/user/${userId}/topic/new_message`, (data) => {
          const parsedResponse = JSON.parse(data);
          dispatch(AddDirectMessage({
            room_id: parsedResponse.conversation_id,
            message: {
              id: parsedResponse.message.id,
              type: "msg",
              subtype: parsedResponse.message.type,
              media: parsedResponse.message.media,
              mediaType: parsedResponse.message.mediaType,
              message: parsedResponse.message.text,
              incoming: parsedResponse.message.to === user_id,
              outgoing: parsedResponse.message.from === user_id,
              time: parsedResponse.message.createdAt,
            }
          }));
        });
        subscriptions.push(new_message);

        const start_conversation = webSocketService.subscribe(`/user/${userId}/topic/start_conversation`, (response) => {
          const parsedResponse = JSON.parse(response);
          dispatch((dispatch, getState) => {
            const existingConversation = getState().conversation.direct_chat.conversations
              ?.find((el) => el.id === parsedResponse.data.id);

            if (existingConversation) {
              dispatch(UpdateDirectConversation({ conversation: parsedResponse.data }));
            } else {
              dispatch(AddDirectConversation({ conversation: parsedResponse.data }));
            }

            dispatch(SelectConversation({ room_id: parsedResponse.data.id, chat_type: "individual" }));
            dispatch(SetCurrentConversation({ room_id: parsedResponse.data.id }));
          });
        });
        subscriptions.push(start_conversation);

        const group_created = webSocketService.subscribe(`/user/${userId}/topic/group_created`, (response) => {
          const parsedResponse = JSON.parse(response);
          const groupData = parsedResponse?.data || parsedResponse;

          if (!groupData?.id) return;

          dispatch((dispatch, getState) => {
            const existingGroup = getState().conversation.group_chat.conversations
              ?.find((el) => el.id === groupData.id);

            if (existingGroup) {
              dispatch(UpdateGroupConversation({ group: groupData }));
            } else {
              dispatch(AddGroupConversation({ group: groupData }));
            }
          });
        });
        subscriptions.push(group_created);

        const group_updated = webSocketService.subscribe(`/user/${userId}/topic/group_updated`, (response) => {
          const parsedResponse = JSON.parse(response);
          const groupData = parsedResponse?.data || parsedResponse;
          if (!groupData?.id) return;

          dispatch((dispatch, getState) => {
            const exists = getState().conversation.group_chat.conversations
              ?.some((group) => group.id === groupData.id);
            dispatch(exists
              ? UpdateGroupConversation({ group: groupData })
              : AddGroupConversation({ group: groupData }));
            if (getState().app.room_id === groupData.id) {
              dispatch(SetCurrentGroup({ room_id: groupData.id }));
            }
          });
        });
        subscriptions.push(group_updated);

        const group_removed = webSocketService.subscribe(`/user/${userId}/topic/group_removed`, (response) => {
          const parsedResponse = JSON.parse(response);
          const groupId = parsedResponse?.group_id || parsedResponse?.data?.group_id;
          if (!groupId) return;
          dispatch((dispatch, getState) => {
            dispatch(RemoveGroupConversation({ group_id: groupId }));
            if (getState().app.room_id === groupId) {
              dispatch(SelectConversation({ room_id: null, chat_type: null }));
            }
          });
        });
        subscriptions.push(group_removed);

        const group_new_message = webSocketService.subscribe(`/user/${userId}/topic/group_new_message`, (response) => {
          const parsedResponse = JSON.parse(response);

          if (!parsedResponse?.group_id || !parsedResponse?.message) {
            return;
          }

          const groupConversation =
            groupConversationsRef.current?.find((el) => el.id === parsedResponse.group_id);
          const sender = groupConversation?.members
            ?.find((member) => member.id?.toString() === parsedResponse.message.from?.toString());

          dispatch(AddGroupMessage({
            group_id: parsedResponse.group_id,
            message: {
              id: parsedResponse.message.id,
              type: "msg",
              subtype: parsedResponse.message.type,
              media: parsedResponse.message.media,
              mediaType: parsedResponse.message.mediaType,
              message: parsedResponse.message.text,
              incoming: parsedResponse.message.from !== userId,
              outgoing: parsedResponse.message.from === userId,
              sender_id: parsedResponse.message.from,
              sender_name:
                parsedResponse.message.senderName ||
                parsedResponse.message.sender_name ||
                parsedResponse.message.fromName ||
                (sender
                  ? `${sender.firstName || ""} ${sender.lastName || ""}`.trim() || sender.email || null
                  : null),
              time: parsedResponse.message.createdAt,
            },
          }));
        });
        subscriptions.push(group_new_message);

        const group_message_deleted = webSocketService.subscribe(`/user/${userId}/topic/group_message_deleted`, (response) => {
          const parsedResponse = JSON.parse(response);

          dispatch(ApplyGroupMessageDeletion({
            group_id: parsedResponse.group_id,
            message_id: parsedResponse.message_id,
            user_id: parsedResponse.user_id,
          }));
        });
        subscriptions.push(group_message_deleted);

        const request_sent = webSocketService.subscribe(`/user/${userId}/topic/notification`, (data) => {
          dispatch(showSnackbar({ severity: "info", message: data }));
        });
        subscriptions.push(request_sent);

    }

    return () => {
      subscriptions.forEach((el) => {
        if (el) {
          webSocketService.unsubscribe(el);
        }
      });
      webSocketService.disconnect();
    };
  }, [dispatch, isLoggedIn, userId, user_id]);

  if (!isLoggedIn) {
    return <Navigate to="/auth/login" />
  }

  return (
    <>
      <Stack direction="row">
        {isDesktop && (
          // SideBar
          <SideNav />
        )}

        <Outlet />
      </Stack>
      {open_audio_notification_dialog && (
        <AudioCallNotification open={open_audio_notification_dialog} handleClose={handleCloseAudioDialog} />
      )}
      {open_audio_dialog && (
        <AudioCallDialog
          open={open_audio_dialog}
          handleClose={handleCloseAudioDialog}
        />
      )}
      {open_video_notification_dialog && (
        <VideoCallNotification open={open_video_notification_dialog} handleClose={handleCloseVideoDialog} />
      )}
      {open_video_dialog && (
        <VideoCallDialog
          open={open_video_dialog}
          handleClose={handleCloseVideoDialog}
        />
      )}
    </>
  );
};

export default DashboardLayout;
