import axios from "axios";
import { BASE_URL } from "../config";

const axiosInstance = axios.create({
    baseURL: BASE_URL,
    withCredentials: true,
    withXSRFToken: true,
    xsrfCookieName: "XSRF-TOKEN",
    xsrfHeaderName: "X-XSRF-TOKEN",
});

axiosInstance.interceptors.response.use(
    (response) => response,
    async (error) => {
        const request = error.config;
        const isSessionEndpoint = request?.url?.includes("/auth/login") || request?.url?.includes("/auth/refresh");
        const method = request?.method?.toLowerCase();
        const isMutation = ["post", "put", "patch", "delete"].includes(method);
        const isCsrfFailure = error.response?.status === 403
            && error.response?.data?.error === "Forbidden"
            && isMutation
            && !request?._csrfRetried;

        if (isCsrfFailure) {
            request._csrfRetried = true;
            await axiosInstance.get("/auth/csrf");
            return axiosInstance(request);
        }

        if (error.response?.status === 401 && request && !request._retried && !isSessionEndpoint) {
            request._retried = true;
            try {
                await axiosInstance.post("/auth/refresh");
                return axiosInstance(request);
            } catch (_) {
                // The caller handles an expired session.
            }
        }
        return Promise.reject(error);
    }
);

export default axiosInstance;
