import React from "react";
import { Box, Stack, Typography } from "@mui/material";
import { alpha, useTheme } from "@mui/material/styles";
import { Navigate, Outlet } from "react-router-dom";
import { ChatCircleDots, Lightning, ShieldCheck } from "phosphor-react";
import { useSelector } from "react-redux";
import LoadingScreen from "../../components/LoadingScreen";
import useResponsive from "../../hooks/useResponsive";

const highlights = [
  { icon: <Lightning size={19} />, title: "Instant", text: "Realtime conversations that keep up." },
  { icon: <ShieldCheck size={19} />, title: "Private", text: "Secure sessions and protected media." },
  { icon: <ChatCircleDots size={19} />, title: "Connected", text: "People and groups in one place." },
];

const AuthLayout = () => {
  const { isLoggedIn, isLoading } = useSelector((state) => state.auth);
  const theme = useTheme();
  const isDesktop = useResponsive("up", "md");

  if (isLoggedIn) return <Navigate to="/app" />;
  if (isLoading) return <LoadingScreen />;

  return (
    <Stack direction="row" sx={{ minHeight: "100vh", p: { xs: 1.5, md: 2 }, overflow: "hidden" }}>
      {isDesktop && (
        <Stack
          justifyContent="space-between"
          sx={{
            position: "relative",
            width: "48%",
            maxWidth: 680,
            minHeight: "calc(100vh - 32px)",
            p: 6,
            overflow: "hidden",
            borderRadius: "28px",
            color: "white",
            background: "linear-gradient(145deg, #18243D 0%, #253B72 48%, #6146A4 115%)",
            boxShadow: "0 30px 90px rgba(29,42,77,.28)",
          }}
        >
          <Box sx={{ position: "absolute", width: 420, height: 420, borderRadius: "50%", right: -150, top: -170, border: "1px solid rgba(255,255,255,.12)", boxShadow: "0 0 0 70px rgba(255,255,255,.025), 0 0 0 140px rgba(255,255,255,.018)" }} />
          <Stack direction="row" spacing={1.25} alignItems="center" sx={{ position: "relative" }}>
            <Box sx={{ width: 44, height: 44, borderRadius: "15px", display: "grid", placeItems: "center", bgcolor: "rgba(255,255,255,.14)", border: "1px solid rgba(255,255,255,.16)", fontSize: 20, fontWeight: 800 }}>C</Box>
            <Typography sx={{ fontSize: 20, fontWeight: 800, letterSpacing: "-.03em" }}>ConnectO</Typography>
          </Stack>
          <Stack spacing={2.5} sx={{ position: "relative", maxWidth: 510 }}>
            <Typography variant="h2" sx={{ fontSize: { md: 43, lg: 52 }, lineHeight: 1.08, letterSpacing: "-.045em" }}>Conversations that feel effortless.</Typography>
            <Typography sx={{ color: "rgba(255,255,255,.7)", fontSize: 16, lineHeight: 1.75, maxWidth: 450 }}>A focused place for your closest people, your busiest teams, and everything worth sharing.</Typography>
          </Stack>
          <Stack direction="row" spacing={1.25} sx={{ position: "relative" }}>
            {highlights.map((item) => (
              <Stack key={item.title} spacing={1} sx={{ flex: 1, p: 2, borderRadius: "18px", bgcolor: "rgba(255,255,255,.08)", border: "1px solid rgba(255,255,255,.1)", backdropFilter: "blur(12px)" }}>
                {item.icon}
                <Typography sx={{ fontSize: 13, fontWeight: 800 }}>{item.title}</Typography>
                <Typography sx={{ fontSize: 11.5, lineHeight: 1.5, color: "rgba(255,255,255,.62)" }}>{item.text}</Typography>
              </Stack>
            ))}
          </Stack>
        </Stack>
      )}

      <Stack alignItems="center" justifyContent="center" sx={{ flex: 1, minWidth: 0, px: { xs: 1, sm: 4 }, py: 4 }}>
        {!isDesktop && (
          <Stack direction="row" spacing={1} alignItems="center" mb={4}>
            <Box sx={{ width: 42, height: 42, borderRadius: "14px", display: "grid", placeItems: "center", color: "white", background: "linear-gradient(135deg, #628BFF, #7356E8)", fontWeight: 800 }}>C</Box>
            <Typography variant="h5">ConnectO</Typography>
          </Stack>
        )}
        <Box sx={{ width: "100%", maxWidth: 460, p: { xs: 2.5, sm: 4.5 }, borderRadius: "24px", bgcolor: alpha(theme.palette.background.paper, 0.82), border: `1px solid ${alpha(theme.palette.text.primary, 0.08)}`, boxShadow: theme.palette.mode === "light" ? "0 24px 70px rgba(31,42,68,.12)" : "0 24px 70px rgba(0,0,0,.36)", backdropFilter: "blur(24px)" }}>
          <Outlet />
        </Box>
      </Stack>
    </Stack>
  );
};

export default AuthLayout;
