import React, { useEffect, useRef, useState } from "react";
import { Dialog, DialogContent, IconButton, Slide, Stack, Typography, } from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import webSocketService from "../../../webSocketService";
import { ResetVideoCallQueue, UpdateCallStatus } from "../../../redux/slices/videoCall";
import { PhoneX } from "phosphor-react";
import {
  createPeerConnection,
  getLocalStream,
  createOffer,
  createAnswer,
  setRemoteAnswer,
  addIceCandidate,
  closePeerConnection,
} from "../../../webrtc/WebRTCHelper";

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const CallDialog = ({ open, handleClose }) => {

  const user_id = window.localStorage.getItem("user_id");
  const dispatch = useDispatch();
  const localStreamRef = useRef(null);
  const peerConnectionRef = useRef(null);
  const subscriptionsRef = useRef([]);

  const [call_details] = useSelector((state) => state.videoCall.call_queue);
  const { incoming, status } = useSelector((state) => state.videoCall);
  const [userBusy, setUserBusy] = useState(false);
  const roomID = call_details?.roomID;
  const streamID = call_details?.streamID;
  const userID = call_details?.userID;

  const handleDisconnect = (event, reason) => {
    if (reason && reason === "backdropClick") {
      return;
    } else {
      webSocketService.sendMessage("/app/end_video_call", JSON.stringify({ ...call_details }));

      closePeerConnection(peerConnectionRef.current, localStreamRef.current);
      peerConnectionRef.current = null;
      localStreamRef.current = null;

      dispatch(ResetVideoCallQueue());
      dispatch(UpdateCallStatus({ status: "" }));
      handleClose();
    }
  };

  const setupPeerConnection = (pc) => {
    peerConnectionRef.current = pc;

    pc.ontrack = (event) => {
      const remoteStream = event.streams[0];
      const remoteAudio = document.getElementById("remote-audio");
      const remoteVideo = document.getElementById("remote-video");
      if (remoteAudio) {
        remoteAudio.srcObject = remoteStream;
        remoteAudio.play();
      }
      if (remoteVideo) {
        remoteVideo.srcObject = remoteStream;
        remoteVideo.play();
      }
    };

    pc.onicecandidate = (event) => {
      if (event.candidate) {
        webSocketService.sendMessage("/app/webrtc_ice_candidate", JSON.stringify({
          to: streamID,
          candidate: event.candidate,
        }));
      }
    };
  };

  const attachLocalStream = (localStream) => {
    const localAudio = document.getElementById("local-audio");
    const localVideo = document.getElementById("local-video");
    if (localAudio) localAudio.srcObject = localStream;
    if (localVideo) {
      localVideo.srcObject = localStream;
      localVideo.play();
    }
  };

  const initiateCall = async () => {
    try {
      const localStream = await getLocalStream(true);
      localStreamRef.current = localStream;
      attachLocalStream(localStream);

      const pc = createPeerConnection();
      setupPeerConnection(pc);

      localStream.getTracks().forEach((track) => pc.addTrack(track, localStream));

      const offer = await createOffer(pc);
      webSocketService.sendMessage("/app/webrtc_offer", JSON.stringify({
        to: streamID,
        sdp: offer,
      }));
    } catch (error) {
      console.error("Failed to initiate call:", error);
    }
  };

  const handleOffer = async (sdp) => {
    try {
      const localStream = await getLocalStream(true);
      localStreamRef.current = localStream;
      attachLocalStream(localStream);

      const pc = createPeerConnection();
      setupPeerConnection(pc);

      localStream.getTracks().forEach((track) => pc.addTrack(track, localStream));

      const answer = await createAnswer(pc, sdp);
      webSocketService.sendMessage("/app/webrtc_answer", JSON.stringify({
        to: streamID,
        sdp: answer,
      }));
    } catch (error) {
      console.error("Failed to handle offer:", error);
    }
  };

  useEffect(() => {

    if (!incoming) {
      webSocketService.sendMessage("/app/start_video_call", JSON.stringify({
        to: call_details?.streamID,
        from: userID,
        roomID,
      }));
    }

    const end_video_call = webSocketService.subscribe(`/user/${user_id}/topic/end_video_call`, (data) => {
      dispatch(UpdateCallStatus({ status: "" }));
      handleDisconnect();
    });
    subscriptionsRef.current.push(end_video_call);

    const video_call_missed = webSocketService.subscribe(`/user/${user_id}/topic/video_call_missed`, (data) => {
      handleDisconnect();
    });
    subscriptionsRef.current.push(video_call_missed);

    const video_call_accepted = webSocketService.subscribe(`/user/${user_id}/topic/video_call_accepted`, (data) => {
      dispatch(UpdateCallStatus({ status: "ONGOING" }));
      if (!incoming) {
        initiateCall();
      }
    });
    subscriptionsRef.current.push(video_call_accepted);

    const video_call_denied = webSocketService.subscribe(`/user/${user_id}/topic/video_call_denied`, (data) => {
      dispatch(UpdateCallStatus({ status: "" }));
      handleDisconnect();
    });
    subscriptionsRef.current.push(video_call_denied);

    const on_another_video_call = webSocketService.subscribe(`/user/${user_id}/topic/on_another_video_call`, (data) => {
      setUserBusy(true);
    });
    subscriptionsRef.current.push(on_another_video_call);

    const webrtc_offer = webSocketService.subscribe(`/user/${user_id}/topic/webrtc_offer`, (data) => {
      const parsed = JSON.parse(data);
      if (parsed.sdp && incoming) {
        handleOffer(parsed.sdp);
      }
    });
    subscriptionsRef.current.push(webrtc_offer);

    const webrtc_answer = webSocketService.subscribe(`/user/${user_id}/topic/webrtc_answer`, (data) => {
      const parsed = JSON.parse(data);
      if (parsed.sdp && peerConnectionRef.current) {
        setRemoteAnswer(peerConnectionRef.current, parsed.sdp);
      }
    });
    subscriptionsRef.current.push(webrtc_answer);

    const webrtc_ice_candidate = webSocketService.subscribe(`/user/${user_id}/topic/webrtc_ice_candidate`, (data) => {
      const parsed = JSON.parse(data);
      if (parsed.candidate && peerConnectionRef.current) {
        addIceCandidate(peerConnectionRef.current, parsed.candidate);
      }
    });
    subscriptionsRef.current.push(webrtc_ice_candidate);

    return () => {
      subscriptionsRef.current.forEach((sub) => {
        webSocketService.unsubscribe(sub);
      });
      subscriptionsRef.current = [];

      closePeerConnection(peerConnectionRef.current, localStreamRef.current);
      peerConnectionRef.current = null;
      localStreamRef.current = null;
    };
  }, []);

  return (
    <>
      <Dialog
        fullWidth
        maxWidth="lg"
        open={open}
        TransitionComponent={Transition}
        keepMounted
        onClose={handleDisconnect}
        aria-describedby="alert-dialog-slide-description"
      >
        <DialogContent sx={{ padding: 0, position: 'relative' }}>
          {userBusy && <Typography variant="h6">{"User Busy on another Call"}</Typography>}
          <Stack direction="row" p={1.5} justifyContent="center" alignItems="center">
            {/* Remote Video Stack */}
            <div style={{ position: 'relative', display: 'inline-block' }}>
              <video
                style={{
                  height: 700,
                  width: "100%",
                  borderRadius: '8px',
                  boxShadow: '0px 0px 10px rgba(0, 0, 0, 0.2)',
                  objectFit: "cover"
                }}
                id="remote-video"
                controls={false}
              />
              <audio id="remote-audio" controls={false} />
              <Typography
                variant="h6"
                sx={{
                  position: 'absolute',
                  bottom: '16px',
                  left: '10px',
                  color: 'white',
                  backgroundColor: 'rgba(0, 0, 0, 0.3)',
                  padding: '4px',
                  borderRadius: '8px',
                }}
              >
                {call_details?.from.firstName}
              </Typography>

              {/* Local Video positioned on top-right of the remote video */}
              <video
                style={{
                  position: 'absolute',
                  top: '10px',
                  right: '10px',
                  height: 150,
                  width: 200,
                  borderRadius: '8px',
                  boxShadow: '0px 0px 10px rgba(0, 0, 0, 0.3)',
                  zIndex: 1,
                }}
                id="local-video"
                controls={false}
              />
              <audio id="local-audio" controls={false} />
              <IconButton
                onClick={() => {
                  handleDisconnect();
                }}
                sx={{
                  position: 'absolute',
                  bottom: '2%',
                  left: '95%',
                  backgroundColor: '#f44336',
                  transition: "0.1s ease-in-out",
                  color: '#fff',
                  '&:hover': { backgroundColor: '#e53935', transform: 'scale3d(1.1, 1.1, 1.1)', },
                  zIndex: 2,
                }}
              >
                <PhoneX size={24} />
              </IconButton>
            </div>
          </Stack>
        </DialogContent>
      </Dialog>
    </>
  );
};

export default CallDialog;
