import React, { useRef, useState, useEffect } from "react";
import { Avatar, Dialog, DialogActions, DialogContent, IconButton, Slide, Stack, Typography, } from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import webSocketService from "../../../webSocketService";
import { ResetAudioCallQueue, UpdateCallStatus } from "../../../redux/slices/audioCall";
import { PhoneX } from "phosphor-react";
import {
  createPeerConnection,
  getLocalStream,
  createOffer,
  createAnswer,
  setRemoteAnswer,
  addIceCandidate,
  closePeerConnection,
} from "../../../webrtc/WebRTCHelper";

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const CallDialog = ({ open, handleClose }) => {

  const user_id = window.localStorage.getItem("user_id");
  const dispatch = useDispatch();
  const localStreamRef = useRef(null);
  const peerConnectionRef = useRef(null);
  const subscriptionsRef = useRef([]);

  const [call_details] = useSelector((state) => state.audioCall.call_queue);
  const { incoming, status } = useSelector((state) => state.audioCall);
  const [userBusy, setUserBusy] = useState(false);
  const roomID = call_details?.roomID;
  const streamID = call_details?.streamID;
  const userID = call_details?.userID;

  const handleDisconnect = (event, reason) => {
    if (reason && reason === "backdropClick") {
      return;
    } else {
      webSocketService.sendMessage("/app/end_audio_call", JSON.stringify({ ...call_details }));

      closePeerConnection(peerConnectionRef.current, localStreamRef.current);
      peerConnectionRef.current = null;
      localStreamRef.current = null;

      dispatch(ResetAudioCallQueue());
      dispatch(UpdateCallStatus({ status: "" }));
      handleClose();
    }
  };

  const setupPeerConnection = (pc) => {
    peerConnectionRef.current = pc;

    pc.ontrack = (event) => {
      const remoteAudio = document.getElementById("remote-audio");
      if (remoteAudio) {
        remoteAudio.srcObject = event.streams[0];
        remoteAudio.play();
      }
    };

    pc.onicecandidate = (event) => {
      if (event.candidate) {
        webSocketService.sendMessage("/app/webrtc_ice_candidate", JSON.stringify({
          to: streamID,
          candidate: event.candidate,
        }));
      }
    };
  };

  const initiateCall = async () => {
    try {
      const localStream = await getLocalStream(false);
      localStreamRef.current = localStream;

      const localAudio = document.getElementById("local-audio");
      if (localAudio) localAudio.srcObject = localStream;

      const pc = createPeerConnection();
      setupPeerConnection(pc);

      localStream.getTracks().forEach((track) => pc.addTrack(track, localStream));

      const offer = await createOffer(pc);
      webSocketService.sendMessage("/app/webrtc_offer", JSON.stringify({
        to: streamID,
        sdp: offer,
      }));
    } catch (error) {
      console.error("Failed to initiate call:", error);
    }
  };

  const handleOffer = async (sdp) => {
    try {
      const localStream = await getLocalStream(false);
      localStreamRef.current = localStream;

      const localAudio = document.getElementById("local-audio");
      if (localAudio) localAudio.srcObject = localStream;

      const pc = createPeerConnection();
      setupPeerConnection(pc);

      localStream.getTracks().forEach((track) => pc.addTrack(track, localStream));

      const answer = await createAnswer(pc, sdp);
      webSocketService.sendMessage("/app/webrtc_answer", JSON.stringify({
        to: streamID,
        sdp: answer,
      }));
    } catch (error) {
      console.error("Failed to handle offer:", error);
    }
  };

  useEffect(() => {

    if (!incoming) {
      webSocketService.sendMessage("/app/start_audio_call", JSON.stringify({
        to: streamID,
        from: userID,
        roomID,
      }));
    }

    const end_audio_call = webSocketService.subscribe(`/user/${user_id}/topic/end_audio_call`, (data) => {
      dispatch(UpdateCallStatus({ status: "" }));
      handleDisconnect();
    });
    subscriptionsRef.current.push(end_audio_call);

    const audio_call_missed = webSocketService.subscribe(`/user/${user_id}/topic/audio_call_missed`, (data) => {
      handleDisconnect();
    });
    subscriptionsRef.current.push(audio_call_missed);

    const audio_call_accepted = webSocketService.subscribe(`/user/${user_id}/topic/audio_call_accepted`, (data) => {
      dispatch(UpdateCallStatus({ status: "ONGOING" }));
      if (!incoming) {
        initiateCall();
      }
    });
    subscriptionsRef.current.push(audio_call_accepted);

    const audio_call_denied = webSocketService.subscribe(`/user/${user_id}/topic/audio_call_denied`, (data) => {
      dispatch(UpdateCallStatus({ status: "" }));
      handleDisconnect();
    });
    subscriptionsRef.current.push(audio_call_denied);

    const on_another_audio_call = webSocketService.subscribe(`/user/${user_id}/topic/on_another_audio_call`, (data) => {
      setUserBusy(true);
    });
    subscriptionsRef.current.push(on_another_audio_call);

    const webrtc_offer = webSocketService.subscribe(`/user/${user_id}/topic/webrtc_offer`, (data) => {
      const parsed = JSON.parse(data);
      if (parsed.sdp && incoming) {
        handleOffer(parsed.sdp);
      }
    });
    subscriptionsRef.current.push(webrtc_offer);

    const webrtc_answer = webSocketService.subscribe(`/user/${user_id}/topic/webrtc_answer`, (data) => {
      const parsed = JSON.parse(data);
      if (parsed.sdp && peerConnectionRef.current) {
        setRemoteAnswer(peerConnectionRef.current, parsed.sdp);
      }
    });
    subscriptionsRef.current.push(webrtc_answer);

    const webrtc_ice_candidate = webSocketService.subscribe(`/user/${user_id}/topic/webrtc_ice_candidate`, (data) => {
      const parsed = JSON.parse(data);
      if (parsed.candidate && peerConnectionRef.current) {
        addIceCandidate(peerConnectionRef.current, parsed.candidate);
      }
    });
    subscriptionsRef.current.push(webrtc_ice_candidate);

    return () => {
      subscriptionsRef.current.forEach((sub) => {
        webSocketService.unsubscribe(sub);
      });
      subscriptionsRef.current = [];

      closePeerConnection(peerConnectionRef.current, localStreamRef.current);
      peerConnectionRef.current = null;
      localStreamRef.current = null;
    };
  }, []);

  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    let timer;
    if (status === "ONGOING") {
      timer = setInterval(() => {
        setSeconds(prevSeconds => prevSeconds + 1);
      }, 1000);
    } else {
      setSeconds(0);
    }

    return () => {
      clearInterval(timer);
    };
  }, [status]);

  const formatTime = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${minutes < 10 ? '0' : ''}${minutes}:${secs < 10 ? '0' : ''}${secs}`;
  };

  return (
    <>
      <Dialog
        open={open}
        TransitionComponent={Transition}
        keepMounted
        onClose={handleDisconnect}
        aria-describedby="alert-dialog-slide-description"
        PaperProps={{
          sx: {
            borderRadius: 3,
            backgroundColor: '#f9fafb',
            boxShadow: 5,
          },
        }}
      >
        <DialogContent>
          <Stack
            direction="column"
            p={1.5}
            justifyContent="center"
            alignItems="center"
          >
            {/* Remote Audio Stack */}
            <Stack direction="column" justifyContent="center" p={2}>
              <Stack alignItems="center">
                <Avatar
                  sx={{ height: 300, width: 300, border: '4px solid #4caf50' }}
                  src={call_details?.from?.avatar}
                />
                <Typography variant="h4" mt={2}>
                  {call_details?.from.firstName}
                </Typography>
              </Stack>
              <audio id="remote-audio" controls={false} />
            </Stack>
            {/* Local Audio Stack */}
            <Stack>
              <audio id="local-audio" controls={false} />
            </Stack>
            <Stack mt={2}>
              <Typography variant="h5">{formatTime(seconds)}</Typography>
              {userBusy && <Typography variant="h6">{"User is on another call"}</Typography>}
            </Stack>
          </Stack>
        </DialogContent>
        <DialogActions sx={{ justifyContent: "center" }}>
          <IconButton
            onClick={handleDisconnect}
            sx={{
              backgroundColor: '#f44336',
              transition: '0.1s ease-in-out',
              color: '#fff',
              '&:hover': {
                backgroundColor: '#e53935',
                transform: 'scale3d(1.1, 1.1, 1.1)',
              },
            }}
          >
            <PhoneX size={40} />
          </IconButton>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default CallDialog;
