import { ICE_SERVERS } from "../config";

export const RTC_CONFIG = { iceServers: ICE_SERVERS };

export const createPeerConnection = (onTrack, onIceCandidate, onConnectionStateChange) => {
  const pc = new RTCPeerConnection(RTC_CONFIG);

  pc.ontrack = (event) => {
    if (onTrack) onTrack(event.streams[0]);
  };

  pc.onicecandidate = (event) => {
    if (event.candidate && onIceCandidate) {
      onIceCandidate(event.candidate);
    }
  };

  if (onConnectionStateChange) {
    pc.onconnectionstatechange = () => onConnectionStateChange(pc.connectionState);
  }

  return pc;
};

export const getLocalStream = async (isVideo) => {
  const constraints = {
    audio: true,
    video: isVideo ? { width: { ideal: 1280 }, height: { ideal: 720 } } : false,
  };
  return await navigator.mediaDevices.getUserMedia(constraints);
};

export const createOffer = async (pc) => {
  const offer = await pc.createOffer();
  await pc.setLocalDescription(offer);
  return pc.localDescription;
};

export const createAnswer = async (pc, remoteSdp) => {
  await pc.setRemoteDescription(new RTCSessionDescription(remoteSdp));
  const answer = await pc.createAnswer();
  await pc.setLocalDescription(answer);
  return pc.localDescription;
};

export const setRemoteAnswer = async (pc, answer) => {
  await pc.setRemoteDescription(new RTCSessionDescription(answer));
};

export const addIceCandidate = async (pc, candidate) => {
  try {
    await pc.addIceCandidate(new RTCIceCandidate(candidate));
  } catch (e) {
    // candidate may arrive before remote description is set
  }
};

export const closePeerConnection = (pc, stream) => {
  if (stream) {
    stream.getTracks().forEach((track) => track.stop());
  }
  if (pc) {
    pc.ontrack = null;
    pc.onicecandidate = null;
    pc.onconnectionstatechange = null;
    pc.close();
  }
};
