import { Avatar, Dialog, DialogActions, DialogContent, IconButton, Slide, Stack, Typography, } from "@mui/material";
import React, { useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { ResetVideoCallQueue, UpdateCallStatus, UpdateVideoCallDialog, } from "../../../redux/slices/videoCall";
import { PhoneCall, PhoneX } from "phosphor-react";
import webSocketService from "../../../webSocketService";
import ringtone from '../../../assets/sounds/ringtone.mp3';


const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const CallNotification = ({ open, handleClose }) => {
  const user_id = window.localStorage.getItem("user_id");
  const dispatch = useDispatch();
  const { user } = useSelector((state) => state.app);
  const [call_details] = useSelector((state) => state.videoCall.call_queue);
  const ringtoneSound = new Audio(ringtone);

  useEffect(() => {
    const end_video_call = webSocketService.subscribe(`/user/${user_id}/topic/end_video_call`, (data) => {
      dispatch(UpdateCallStatus({ status: "" }));
      dispatch(ResetVideoCallQueue());
      handleClose();
    });

    if (open) {
      ringtoneSound.play();
    }

    return () => {
      ringtoneSound.pause();
      ringtoneSound.currentTime = 0
      webSocketService.unsubscribe(end_video_call);
    }
  }, [open]);

  const handleAccept = () => {
    webSocketService.sendMessage("/app/video_call_accepted", JSON.stringify({ ...call_details }));
    dispatch(UpdateVideoCallDialog({ state: true }));
  };

  const handleDeny = () => {
    webSocketService.sendMessage("/app/video_call_denied", JSON.stringify({ ...call_details }));
    dispatch(ResetVideoCallQueue());
    handleClose();
  };

  return (
    <>
      <Dialog
        open={open}
        TransitionComponent={Transition}
        keepMounted
        onClose={handleDeny}
        aria-describedby="alert-dialog-slide-description"
        PaperProps={{
          sx: {
            borderRadius: 3, // Rounder corners
            backgroundColor: '#f9fafb', // Light background
            boxShadow: 5, // Subtle shadow
          },
        }}
      >
        <DialogContent sx={{ padding: 4 }}>
          <Stack direction="row" justifyContent="center" spacing={6} p={2}>
            <Stack alignItems="center">
              <Avatar
                sx={{ height: 300, width: 300, border: '4px solid #4caf50' }} // Add border for contrast
                src={call_details?.from?.avatar}
              />
              <Typography variant="h4" mt={2}>
                {call_details?.from.firstName}
              </Typography>
            </Stack>
            <Stack alignItems="center">
              <Avatar
                sx={{ height: 120, width: 120, border: '4px solid #2196f3' }} // Add border for user
                src={user?.avatar}
              />
              <Typography variant="body1" mt={2}>
                You
              </Typography>
            </Stack>
          </Stack>
        </DialogContent>
        <DialogActions sx={{ justifyContent: 'space-evenly' }}>
          <Stack alignItems={'center'}>
            <IconButton
              onClick={handleAccept}
              sx={{
                backgroundColor: '#4caf50',
                color: '#fff',
                '&:hover': { backgroundColor: '#43a047' }, // Slightly darker on hover
                padding: 2,
              }}
            >
              <PhoneCall size={40} />
            </IconButton>
            <Typography variant="button" >Accept</Typography>
          </Stack>
          <Stack alignItems={'center'}>
            <IconButton
              onClick={handleDeny}
              sx={{
                backgroundColor: '#f44336',
                color: '#fff',
                '&:hover': { backgroundColor: '#e53935' }, // Slightly darker on hover
                padding: 2,
              }}
            >
              <PhoneX size={40} />
            </IconButton>
            <Typography variant="button">Deny</Typography>
          </Stack>
        </DialogActions>
      </Dialog>
    </>

  );
};

export default CallNotification;