import React from "react";
import { alpha, useTheme } from "@mui/material/styles";
import { Box, IconButton, Stack, Tooltip, Typography } from "@mui/material";
import { Moon, Sun } from "phosphor-react";
import useSettings from "../../hooks/useSettings";
import { Nav_Buttons, Nav_Setting } from "../../data";
import ProfileMenu from "./ProfileMenu";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { UpdateTab } from "../../redux/slices/app";

const paths = ["/app", "/group", "/call", "/settings"];

const SideNav = () => {
  const theme = useTheme();
  const { tab } = useSelector((state) => state.app);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { onToggleMode } = useSettings();
  const items = [...Nav_Buttons, ...Nav_Setting];

  const select = (index) => {
    dispatch(UpdateTab({ tab: index }));
    navigate(paths[index] || "/app");
  };

  return (
    <Box
      component="nav"
      aria-label="Primary navigation"
      sx={{
        position: "relative",
        zIndex: 20,
        height: "100vh",
        width: 88,
        flexShrink: 0,
        borderRight: `1px solid ${alpha(theme.palette.text.primary, 0.08)}`,
        bgcolor: alpha(theme.palette.background.paper, 0.78),
        backdropFilter: "blur(24px) saturate(150%)",
      }}
    >
      <Stack py={2.5} px={1.5} alignItems="center" justifyContent="space-between" height="100%">
        <Stack alignItems="center" spacing={4} width="100%">
          <Tooltip title="ConnectO" placement="right">
            <Box
              aria-label="ConnectO home"
              onClick={() => select(0)}
              sx={{
                width: 50,
                height: 50,
                borderRadius: "17px",
                display: "grid",
                placeItems: "center",
                color: "white",
                cursor: "pointer",
                background: "linear-gradient(145deg, #6C92FF 0%, #4F7CFF 52%, #7B5CF5 120%)",
                boxShadow: "0 12px 28px rgba(79,124,255,.3), inset 0 1px rgba(255,255,255,.35)",
              }}
            >
              <Typography sx={{ fontWeight: 800, fontSize: 22, letterSpacing: "-0.06em" }}>C</Typography>
            </Box>
          </Tooltip>

          <Stack spacing={1.25} width="100%">
            {items.map((item) => {
              const active = item.index === tab;
              return (
                <Tooltip key={item.index} title={item.title} placement="right" arrow>
                  <IconButton
                    aria-label={item.title}
                    aria-current={active ? "page" : undefined}
                    onClick={() => select(item.index)}
                    sx={{
                      width: 56,
                      height: 52,
                      color: active ? theme.palette.primary.main : theme.palette.text.secondary,
                      bgcolor: active ? alpha(theme.palette.primary.main, 0.12) : "transparent",
                      border: `1px solid ${active ? alpha(theme.palette.primary.main, 0.18) : "transparent"}`,
                      "& svg": { width: 23, height: 23 },
                      "&::before": active ? {
                        content: '""', position: "absolute", left: -13, width: 4, height: 24,
                        borderRadius: "0 6px 6px 0", bgcolor: "primary.main",
                      } : {},
                    }}
                  >
                    {item.icon}
                  </IconButton>
                </Tooltip>
              );
            })}
          </Stack>
        </Stack>

        <Stack spacing={1.5} alignItems="center">
          <Tooltip title={`Use ${theme.palette.mode === "dark" ? "light" : "dark"} mode`} placement="right">
            <IconButton
              aria-label="Toggle color theme"
              onClick={onToggleMode}
              sx={{ width: 46, height: 46, color: "text.secondary", bgcolor: alpha(theme.palette.text.primary, 0.04) }}
            >
              {theme.palette.mode === "dark" ? <Sun size={21} /> : <Moon size={21} />}
            </IconButton>
          </Tooltip>
          <ProfileMenu />
        </Stack>
      </Stack>
    </Box>
  );
};

export default SideNav;
