import { createSlice } from "@reduxjs/toolkit";

import axios from "../../utils/axios";
import { ClearApp, showSnackbar } from "./app";
import { ClearConversation } from "./conversation";

// ----------------------------------------------------------------------

const initialState = {
    isLoggedIn: false,
    isInitialized: false,
    isLoading: false,
    user: null,
    user_id: null,
    email: "",
    error: false,
}

const slice = createSlice({
    name: "auth",
    initialState,
    reducers: {
        updateIsLoading(state, action) {
            state.error = action.payload.error;
            state.isLoading = action.payload.isLoading;
        },
        logIn(state, action) {
            state.isLoggedIn = action.payload.isLoggedIn;
            state.user_id = action.payload.user_id;
        },
        signOut(state, action) {
            state.isLoggedIn = false;
            state.user_id = null;
            state.user = null;
        },
        initialize(state) {
            state.isInitialized = true;
        },
        updateRegisterEmail(state, action) {
            state.email = action.payload.email;
        },
        setUser(state, action) {
            state.user = action.payload.user;
        }
    },
});

// Reducer
export default slice.reducer;

export function LoginUser(formValues) {
    return async (dispatch, getState) => {
        // Make API call here

        dispatch(slice.actions.updateIsLoading({ isLoading: true, error: false }));

        await axios.post("/auth/login", {
            ...formValues,
        }, {
            headers: {
                "Content-Type": "application/json",
            }
        }).then(async function (response) {
            await axios.get("/auth/csrf");
            dispatch(slice.actions.logIn({
                isLoggedIn: true,
                user_id: response.data.user_id,
            }));
            window.localStorage.setItem("user_id", response.data.user_id);
            dispatch(slice.actions.setUser({ user: response.data.user }));
            dispatch(showSnackbar({ severity: "success", message: response.data.message }));
            dispatch(slice.actions.updateIsLoading({ isLoading: false, error: false }));
        }).catch(function (error) {
            // console.log(error);
            dispatch(showSnackbar({ severity: "error", message: error.response ? error.response.data.message : error.message }));
            dispatch(slice.actions.updateIsLoading({ isLoading: false, error: true }));
        });
    }
};

export function LogoutUser() {
    return async (dispatch) => {
        try {
            await axios.post("/auth/logout");
        } catch (_) {
            // Local logout still completes if the session has already expired.
        }
        window.localStorage.removeItem("user_id");
        window.localStorage.clear();
        await dispatch(slice.actions.signOut());  // Triggers the rootReducer to clear state
        await dispatch(ClearApp());
        await dispatch(ClearConversation());
    };
}


