export function RegisterUser(formValues, navigate) {
    return async (dispatch, getState) => {
        dispatch(slice.actions.updateIsLoading({ isLoading: true, error: false }));

        await axios.post("/auth/register", {
            ...formValues,
        }, {
            headers: {
                "Content-Type": "application/json",
            }
        }).then(async function (response) {
            if (response.data.auth_type === "GOOGLE") {
                await axios.get("/auth/csrf");
                window.localStorage.setItem("user_id", response.data.user_id);
                dispatch(slice.actions.logIn({
                    isLoggedIn: true,
                    user_id: response.data.user_id,
                }));
            } else {
                dispatch(slice.actions.updateRegisterEmail({ email: formValues.email, }));
                navigate("/auth/verify");
            }
            dispatch(showSnackbar({ severity: "success", message: response.data.message }));
            dispatch(slice.actions.updateIsLoading({ isLoading: false, error: false }));
        }).catch(function (error) {
            // console.log(error);
            dispatch(showSnackbar({ severity: "error", message: error.response ? error.response.data.message : error.message }));
            dispatch(slice.actions.updateIsLoading({ isLoading: false, error: true }));
        });
    };
}

export function VerifyEmail(formValues) {
    return async (dispatch, getState) => {
        dispatch(slice.actions.updateIsLoading({ isLoading: true, error: false }));

        await axios.post("/auth/verify", {
            ...formValues,
        }, {
            headers: {
                "Content-Type": "application/json",
            }
        }).then(async function (response) {
            if (response.data.status === true) {
                await axios.get("/auth/csrf");
                dispatch(slice.actions.logIn({
                    isLoggedIn: true,
                    user_id: response.data.user_id,
                }));
                dispatch(slice.actions.updateRegisterEmail({
                    email: "",
                }))
                window.localStorage.setItem("user_id", response.data.user_id);
                dispatch(slice.actions.setUser({ user: response.data.user }));
                dispatch(showSnackbar({ severity: "success", message: response.data.message }));
            }
            dispatch(
                slice.actions.updateIsLoading({ isLoading: false, error: false })
            );
        }).catch(function (error) {
            dispatch(showSnackbar({ severity: "error", message: error.response ? error.response.data.message : error.message }));
            dispatch(slice.actions.updateIsLoading({ error: true, isLoading: false })
            );
        });
    };
};

export const UpdateIsLoading = (data) => {
    return async (dispatch, getState) => {
        dispatch(slice.actions.updateIsLoading(data));
    }
}

export const RestoreSession = () => {
    return async (dispatch) => {
        try {
            await axios.get("/auth/csrf");
            const response = await axios.get("/auth/me");
            dispatch(slice.actions.logIn({
                isLoggedIn: true,
                user_id: response.data.user_id,
            }));
            dispatch(slice.actions.setUser({ user: response.data.user }));
            window.localStorage.setItem("user_id", response.data.user_id);
        } catch (_) {
            dispatch(slice.actions.signOut());
            window.localStorage.removeItem("user_id");
        } finally {
            dispatch(slice.actions.initialize());
        }
    };
};
